package com.glugglug;

public enum GlugChatStyle
{
	/**
	 * A game message, the kind the game itself prints ("You feel stronger"). Uses the
	 * configured chat text, so it can name the player.
	 */
	GAME_MESSAGE("Game message"),

	/**
	 * A public chat line, so the chatbox shows "Name: glub glub" exactly as it would if the
	 * player had typed it. The message itself is the overhead text.
	 */
	PUBLIC_CHAT("Public chat");

	private final String name;

	GlugChatStyle(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.glugglug;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GlugGlugConfig.GROUP)
public interface GlugGlugConfig extends Config
{
	String GROUP = "glugglug";

	@ConfigSection(
		name = "Overhead text",
		description = "The text that floats above the drinker's head.",
		position = 0
	)
	String overheadSection = "overheadSection";

	@ConfigSection(
		name = "Chat message",
		description = "The message printed into your chatbox.",
		position = 10
	)
	String chatSection = "chatSection";

	@ConfigSection(
		name = "What counts as a chug",
		description = "Which drinking actions trigger the glub.",
		position = 20
	)
	String triggerSection = "triggerSection";

	// ------------------------------------------------------------------
	// Overhead
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "showOverhead",
		name = "Show overhead text",
		description = "Float the text above the drinker's head, like normal public chat.",
		position = 1,
		section = overheadSection
	)
	default boolean showOverhead()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadText",
		name = "Overhead text",
		description = "What appears above their head.",
		position = 2,
		section = overheadSection
	)
	default String overheadText()
	{
		return "glub glub";
	}

	@Range(min = 1, max = 20)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "overheadDuration",
		name = "Duration",
		description = "How long the overhead text stays up, in game ticks (1 tick = 0.6s).",
		position = 3,
		section = overheadSection
	)
	default int overheadDurationTicks()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "keepExistingOverhead",
		name = "Don't interrupt real chat",
		description = "If the player is already saying something overhead, leave their message alone.",
		position = 4,
		section = overheadSection
	)
	default boolean keepExistingOverhead()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Chat
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "showChat",
		name = "Show chat message",
		description = "Print a message in your chatbox when someone chugs.",
		position = 11,
		section = chatSection
	)
	default boolean showChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatStyle",
		name = "Chat style",
		description = "Game message prints a line from the game, using the chat text below. "
			+ "Public chat prints \"Name: glub glub\" in your public chat tab, exactly as it "
			+ "would look if they had typed it - the chat text below is then ignored and the "
			+ "overhead text is used as the words.",
		position = 12,
		section = chatSection
	)
	default GlugChatStyle chatStyle()
	{
		return GlugChatStyle.GAME_MESSAGE;
	}

	@ConfigItem(
		keyName = "chatText",
		name = "Chat text",
		description = "The message itself, for the Game message style. Use $name for the player's name.",
		position = 13,
		section = chatSection
	)
	default String chatText()
	{
		return "$name: glub glub";
	}

	@Range(min = 0, max = 100)
	@Units(Units.TICKS)
	@ConfigItem(
		keyName = "chatCooldown",
		name = "Chat cooldown",
		description = "Minimum ticks between chat messages for the same player, so a 5-dose chug doesn't spam. 0 disables the cooldown.",
		position = 14,
		section = chatSection
	)
	default int chatCooldownTicks()
	{
		return 8;
	}

	// ------------------------------------------------------------------
	// Triggers
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "includeOtherPlayers",
		name = "Include other players",
		description = "Glub for everyone you can see, not just yourself.",
		position = 21,
		section = triggerSection
	)
	default boolean includeOtherPlayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeNormalPotions",
		name = "Also normal potions and food",
		description = "Trigger on the ordinary eat/drink animation too, not only the chugging barrel. Noisy.",
		position = 22,
		section = triggerSection
	)
	default boolean includeNormalPotions()
	{
		return false;
	}
}

package com.glugglug;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Glub Glub",
	description = "Says \"glub glub\" in chat and above your head when you drink from the chugging barrel",
	tags = {"glub", "glug", "chug", "chugging", "barrel", "potion", "drink", "mixology", "overhead"}
)
public class GlugGlugPlugin extends Plugin
{
	/**
	 * The chugging barrel's own drink animation. The barrel was called the "pre-pot device"
	 * before it was renamed in October 2024, which is the name the game data still uses.
	 * Animations are sent to every nearby client, so this fires for other players too.
	 */
	static final int CHUGGING_BARREL_ANIMATION = AnimationID.PREPOT_DEVICE_DRINK_FULL;

	/** The ordinary eat/drink animation, used for normal potions. Off by default. */
	static final int EAT_DRINK_ANIMATION = AnimationID.HUMAN_EAT;

	/**
	 * Overhead text is hidden once the actor's overhead cycle counter runs out. We re-arm it
	 * every game tick with a value comfortably larger than one tick (600ms), so the text never
	 * lapses between ticks and we keep full control of how long it stays up.
	 */
	private static final int OVERHEAD_CYCLES = 100;

	private static final String NAME_TOKEN = "$name";

	@Inject
	private Client client;

	@Inject
	private GlugGlugConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	/** Players currently showing our overhead text, and how many ticks they have left. */
	private final Map<Player, ActiveGlug> active = new HashMap<>();

	/** Last tick we printed a chat message for a given player, for the cooldown. */
	private final Map<String, Integer> lastChatTick = new HashMap<>();

	private int tick;

	@Provides
	GlugGlugConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GlugGlugConfig.class);
	}

	@Override
	protected void shutDown()
	{
		// Put everyone's overhead text back the way we found it before we go.
		for (Map.Entry<Player, ActiveGlug> entry : active.entrySet())
		{
			clearOverhead(entry.getKey(), entry.getValue());
		}
		active.clear();
		lastChatTick.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			// The actors we were tracking no longer exist, so there is nothing to restore.
			active.clear();
			lastChatTick.clear();
		}
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		active.remove(event.getPlayer());
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		final Actor actor = event.getActor();
		if (!(actor instanceof Player))
		{
			return;
		}

		final Player player = (Player) actor;
		if (!isChugAnimation(player.getAnimation()))
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		final boolean isLocalPlayer = local != null && player == local;
		if (!isLocalPlayer && !config.includeOtherPlayers())
		{
			return;
		}

		log.debug("chug detected for {} (animation {})", player.getName(), player.getAnimation());

		if (config.showOverhead())
		{
			showOverhead(player);
		}

		if (config.showChat())
		{
			sendChatMessage(player);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;

		final Iterator<Map.Entry<Player, ActiveGlug>> it = active.entrySet().iterator();
		while (it.hasNext())
		{
			final Map.Entry<Player, ActiveGlug> entry = it.next();
			final Player player = entry.getKey();
			final ActiveGlug glug = entry.getValue();

			// If something else has taken over their overhead text (real public chat, say),
			// stop fighting it and let go.
			if (!glug.text.equals(player.getOverheadText()))
			{
				it.remove();
				continue;
			}

			if (--glug.ticksRemaining <= 0)
			{
				clearOverhead(player, glug);
				it.remove();
				continue;
			}

			// Re-arm so the text survives until we decide to drop it.
			player.setOverheadCycle(OVERHEAD_CYCLES);
		}
	}

	boolean isChugAnimation(int animation)
	{
		if (animation == CHUGGING_BARREL_ANIMATION)
		{
			return true;
		}
		return config.includeNormalPotions() && animation == EAT_DRINK_ANIMATION;
	}

	private void showOverhead(Player player)
	{
		final String text = config.overheadText();
		if (text == null || text.trim().isEmpty())
		{
			return;
		}

		final ActiveGlug existing = active.get(player);
		if (existing == null && config.keepExistingOverhead())
		{
			// They are mid-sentence; don't talk over them.
			final String current = player.getOverheadText();
			if (current != null && !current.isEmpty())
			{
				return;
			}
		}

		final ActiveGlug glug = existing != null
			? existing
			: new ActiveGlug(text, player.getOverheadText());

		// A fresh gulp refreshes the timer, and picks up any config edit to the text.
		glug.text = text;
		glug.ticksRemaining = Math.max(1, config.overheadDurationTicks());
		active.put(player, glug);

		player.setOverheadText(text);
		player.setOverheadCycle(OVERHEAD_CYCLES);
	}

	private void clearOverhead(Player player, ActiveGlug glug)
	{
		// Only clear text that is still ours.
		if (glug.text.equals(player.getOverheadText()))
		{
			player.setOverheadText(glug.previousText);
			player.setOverheadCycle(0);
		}
	}

	private void sendChatMessage(Player player)
	{
		final boolean publicChat = config.chatStyle() == GlugChatStyle.PUBLIC_CHAT;

		// The public chat style says the overhead words, as if they had typed them. The game
		// message style uses its own template, which can name the player.
		final String body = publicChat ? config.overheadText() : config.chatText();
		if (body == null || body.trim().isEmpty())
		{
			return;
		}

		final String name = cleanName(player.getName());
		final int cooldown = config.chatCooldownTicks();
		if (cooldown > 0)
		{
			final Integer last = lastChatTick.get(name);
			if (last != null && tick - last < cooldown)
			{
				return;
			}
		}
		lastChatTick.put(name, tick);

		if (publicChat)
		{
			// Renders as "Name: glub glub" in the public chat tab, the same as a typed message.
			client.addChatMessage(ChatMessageType.PUBLICCHAT, name, body, null);
			return;
		}

		final String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(formatChatMessage(body, name))
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/**
	 * Substitutes the player's name into the configured template. Visible for testing.
	 */
	static String formatChatMessage(String template, String playerName)
	{
		return template.replace(NAME_TOKEN, playerName == null ? "" : playerName);
	}

	/**
	 * Player names arrive with non-breaking spaces in them. Visible for testing.
	 */
	static String cleanName(String name)
	{
		return name == null ? "" : name.replace(' ', ' ');
	}

	private static final class ActiveGlug
	{
		private String text;
		private final String previousText;
		private int ticksRemaining;

		private ActiveGlug(String text, String previousText)
		{
			this.text = text;
			this.previousText = previousText;
		}
	}
}

package com.glugglug;

import static org.junit.Assert.assertEquals;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Test;

public class GlugGlugPluginTest
{
	/**
	 * Launches a RuneLite client with this plugin side-loaded, for manual testing.
	 */
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GlugGlugPlugin.class);
		RuneLite.main(args);
	}

	@Test
	public void substitutesPlayerName()
	{
		assertEquals("Zezima: glub glub", GlugGlugPlugin.formatChatMessage("$name: glub glub", "Zezima"));
	}

	@Test
	public void leavesTemplateAloneWithoutToken()
	{
		assertEquals("glub glub", GlugGlugPlugin.formatChatMessage("glub glub", "Zezima"));
	}

	@Test
	public void substitutesEveryOccurrence()
	{
		assertEquals("Bob glubs, Bob", GlugGlugPlugin.formatChatMessage("$name glubs, $name", "Bob"));
	}

	@Test
	public void toleratesMissingName()
	{
		assertEquals(": glub glub", GlugGlugPlugin.formatChatMessage("$name: glub glub", null));
	}

	@Test
	public void replacesNonBreakingSpacesInNames()
	{
		assertEquals("Some Guy", GlugGlugPlugin.cleanName("Some Guy"));
	}

	@Test
	public void toleratesNullName()
	{
		assertEquals("", GlugGlugPlugin.cleanName(null));
	}
}
